CREATE TABLE IF NOT EXISTS scale_meta(key text PRIMARY KEY,value jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS companies(tenant_id text PRIMARY KEY,company_name text NOT NULL,industry text NOT NULL,registered_city text NOT NULL,created_at date NOT NULL);
CREATE TABLE IF NOT EXISTS products(tenant_id text NOT NULL,sku text NOT NULL,sku_no integer NOT NULL,name text NOT NULL,category text NOT NULL,spec text NOT NULL,unit text NOT NULL,sale_price numeric(12,2) NOT NULL,cost_price numeric(12,2) NOT NULL,supplier text NOT NULL,warranty_months integer NOT NULL,description text NOT NULL,PRIMARY KEY(tenant_id,sku),UNIQUE(tenant_id,sku_no));
CREATE INDEX IF NOT EXISTS products_category_idx ON products(tenant_id,category,sku);
CREATE TABLE IF NOT EXISTS warehouses(tenant_id text NOT NULL,warehouse_id text NOT NULL,warehouse_name text NOT NULL,address text NOT NULL,manager_employee_id text NOT NULL,PRIMARY KEY(tenant_id,warehouse_id));
CREATE TABLE IF NOT EXISTS locations(tenant_id text NOT NULL,warehouse_id text NOT NULL,location_id text NOT NULL,zone text NOT NULL,aisle integer NOT NULL,rack integer NOT NULL,capacity_units integer NOT NULL,PRIMARY KEY(tenant_id,warehouse_id,location_id));
CREATE TABLE IF NOT EXISTS inventory(tenant_id text NOT NULL,warehouse_id text NOT NULL,warehouse_name text NOT NULL,location_id text NOT NULL,sku text NOT NULL,product_name text NOT NULL,stock integer NOT NULL CHECK(stock>=0),reserved integer NOT NULL CHECK(reserved>=0 AND reserved<=stock),reorder_level integer NOT NULL,last_counted_at timestamptz NOT NULL,PRIMARY KEY(tenant_id,warehouse_id,sku));
CREATE TABLE IF NOT EXISTS orders(tenant_id text NOT NULL,order_id text NOT NULL,warehouse_id text NOT NULL,order_type text NOT NULL CHECK(order_type IN ('purchase','sales')),status text NOT NULL,created_at timestamptz NOT NULL,counterparty text NOT NULL,employee_id text NOT NULL,total_amount numeric(16,2) NOT NULL,delivery_address text NOT NULL,order_note text NOT NULL,PRIMARY KEY(tenant_id,order_id));
CREATE INDEX IF NOT EXISTS orders_warehouse_date_idx ON orders(tenant_id,warehouse_id,created_at DESC);
CREATE TABLE IF NOT EXISTS order_items(tenant_id text NOT NULL,order_id text NOT NULL,line_no integer NOT NULL,warehouse_id text NOT NULL,sku text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price numeric(12,2) NOT NULL,line_total numeric(16,2) NOT NULL,PRIMARY KEY(tenant_id,order_id,line_no));
CREATE INDEX IF NOT EXISTS order_items_sku_idx ON order_items(tenant_id,warehouse_id,sku);
CREATE TABLE IF NOT EXISTS stock_movements(tenant_id text NOT NULL,movement_id text NOT NULL,warehouse_id text NOT NULL,location_id text NOT NULL,sku text NOT NULL,movement_type text NOT NULL CHECK(movement_type IN ('inbound','outbound')),quantity integer NOT NULL CHECK(quantity>0),occurred_at timestamptz NOT NULL,document_no text NOT NULL,order_id text NOT NULL,line_no integer NOT NULL,operator_employee_id text NOT NULL,reason text NOT NULL,PRIMARY KEY(tenant_id,movement_id));
CREATE INDEX IF NOT EXISTS stock_movements_warehouse_date_idx ON stock_movements(tenant_id,warehouse_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS stock_movements_sku_date_idx ON stock_movements(tenant_id,warehouse_id,sku,occurred_at DESC);
CREATE TABLE IF NOT EXISTS after_sales(tenant_id text NOT NULL,ticket_id text NOT NULL,warehouse_id text NOT NULL,order_id text NOT NULL,line_no integer NOT NULL,sku text NOT NULL,customer_name text NOT NULL,opened_at timestamptz NOT NULL,status text NOT NULL,issue_type text NOT NULL,description text NOT NULL,warranty_expires date NOT NULL,handling_note text NOT NULL,PRIMARY KEY(tenant_id,ticket_id));
CREATE INDEX IF NOT EXISTS after_sales_warehouse_date_idx ON after_sales(tenant_id,warehouse_id,opened_at DESC);
